import re
L=open('rich2018c.txt').read().split('\n')
for i in list(range(168,211))+list(range(581,599)):
    s=L[i-1]
    for m in re.finditer(r'[^.]*(?:shock|AU|km|%)[^.]*\.', s):
        t=m.group(0).strip()
        if re.search(r'\d', t) and ('shock' in t or 'ENLIL' in t or 'model' in t) and len(t)<700:
            print(i, '|', t)
EOF",
  "description": "Extract quantitative shock sentences from review sections"
}

