{
  "command": "sleep 2; curl -s "https://export.arxiv.org/api/query?id_list=1406.0293,2102.06617,2405.09693,2605.01613,2210.00455&max_results=10" | python3 -I -c "
import sys,re
t=sys.stdin.read()
for e in re.findall(r'<entry>(.*?)</entry>',t,re.S):
    g=lambda p: (re.search(p,e,re.S).group(1) if re.search(p,e,re.S) else None)
    print(g(r'<id>(.*?)</id>'),'|',re.sub(r'\s+',' ',g(r'<title>(.*?)</title>')),'|',g(r'<arxiv:journal_ref[^>]*>(.*?)</arxiv:journal_ref>'),'|',g(r'<arxiv:doi[^>]*>(.*?)</arxiv:doi>'),'|',g(r'<published>(.*?)</published>'))
"",
  "description": "Get journal refs from arXiv metadata"
}

